-- composition of rule kernels cte_inlining x unused_columns (duckdb), template not_exists
SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT TRUE AS c0, [1, 2, 3]::int[] AS c1, 1.5::numeric AS c2, LEAST (LEAST (1.5::numeric, (SELECT MAX (100.0::numeric) FROM v0 AS a2 WHERE COALESCE (COALESCE ((a1.c0 BETWEEN 16 AND 3), TRUE), FALSE))), NULL::numeric) AS c3 FROM v0 AS a1) AS ka WHERE NOT EXISTS (SELECT 1 FROM (SELECT 0.5::numeric AS c0, 'a'::text AS c1 FROM t0 AS a1 GROUP BY a1.c2) AS kb);
-- pgfuzz:check kernel:not_exists SELECT CASE WHEN (SELECT count(*) FROM (SELECT 0.5::numeric AS c0, 'a'::text AS c1 FROM t0 AS a1 GROUP BY a1.c2) AS kb) = 0 THEN (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT TRUE AS c0, [1, 2, 3]::int[] AS c1, 1.5::numeric AS c2, LEAST (LEAST (1.5::numeric, (SELECT MAX (100.0::numeric) FROM v0 AS a2 WHERE COALESCE (COALESCE ((a1.c0 BETWEEN 16 AND 3), TRUE), FALSE))), NULL::numeric) AS c3 FROM v0 AS a1) AS ka) ELSE 0 END
